using MovieInfoBackend.DataModels;
using Xunit.Abstractions;

public class TmdbMovieDataModelTests
{
    private string tmdbHttpClientMovieCreditsResponse;
    private string tmdbHttpClientMovieResponse;

    public TmdbMovieDataModelTests(ITestOutputHelper output)
    {
        // Arrange

        string testMovieCreditsDataFilename = "TmdbHttpClientMovieCreditsResponse.json";
        string testMovieDataFilename = "TmdbHttpClientMovieResponse.json";

        using (StreamReader sr = File.OpenText($"../../../TestData/{testMovieCreditsDataFilename}"))
        {
            tmdbHttpClientMovieCreditsResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientMovieCreditsResponse))
        {
            throw new ArgumentException($"{testMovieCreditsDataFilename} is not valid test data.");
        }

        using (StreamReader sr = File.OpenText($"../../../TestData/{testMovieDataFilename}"))
        {
            tmdbHttpClientMovieResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientMovieResponse))
        {
            throw new ArgumentException($"{testMovieDataFilename} is not valid test data.");
        }
    }

    [Fact]
    public void GetModelFromResponse_ValidResponse_ReturnsValidModels()
    {
        // Act
        
        TmdbMovieResponseDataModel? movieResponse = TmdbHttpClient.GetMovieModelFromResponse(tmdbHttpClientMovieResponse);
        TmdbMovieCreditsResponseDataModel? movieCreditsResponse = TmdbHttpClient.GetMovieCreditsModelFromResponse(tmdbHttpClientMovieCreditsResponse);
        
        // Assert

        // Movie
        Assert.NotNull(movieResponse);
        Assert.False(String.IsNullOrWhiteSpace(movieResponse.BackdropPath), "Movie BackdropPath must not be empty");
        Assert.True(movieResponse.Budget >= 0, "Movie Budget must not be a negative number");
        Assert.NotEmpty(movieResponse.Genres);  // no need to test members since it is handled in a separate test suite, TmdbGenreDataModelTests
        Assert.True(movieResponse.TmdbId > 0, "Movie TmdbId must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(movieResponse.ImdbId), "Movie ImdbId must not be empty");
        Assert.NotEmpty(movieResponse.OriginCountry);
        Assert.False(String.IsNullOrWhiteSpace(movieResponse.OriginalLanguage), "Movie OriginalLanguage must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(movieResponse.OriginalTitle), "Movie OriginalTitle must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(movieResponse.Overview), "Movie Overview must not be empty");
        Assert.True(movieResponse.Popularity >= 0.0, "Movie Popularity must not be a negative decimal number");
        Assert.False(String.IsNullOrWhiteSpace(movieResponse.PosterPath), "Movie PosterPath must not be empty");
        Assert.NotEmpty(movieResponse.ProductionCountries);
        TmdbProductionCountryDataModel firstProductionCountry = movieResponse.ProductionCountries[0];
        Assert.False(String.IsNullOrWhiteSpace(firstProductionCountry.Iso31661), "Movie production company Iso31661 must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstProductionCountry.Name), "Movie production company Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(movieResponse.ReleaseDate), "Movie ReleaseDate must not be empty");
        Assert.True(movieResponse.Revenue >= 0, "Movie Revenue must not be a negative number");
        Assert.True(movieResponse.Runtime > 0, "Movie Runtime must be a positive number");
        Assert.NotEmpty(movieResponse.SpokenLanguages);
        TmdbSpokenLanguageDataModel firstSpokenLanguage = movieResponse.SpokenLanguages[0];
        Assert.False(String.IsNullOrWhiteSpace(firstSpokenLanguage.EnglishName), "Movie spoken language EnglishName must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstSpokenLanguage.Iso6391), "Movie spoken language Iso6391 must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstSpokenLanguage.Name), "Movie spoken language Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(movieResponse.Status), "Movie Status must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(movieResponse.Title), "Movie Title must not be empty");
        Assert.True(movieResponse.VoteAverage >= 0.0, "Movie VoteAverage must not be a negative decimal number");
        Assert.True(movieResponse.VoteCount >= 0, "Movie VoteCount must not be a negative number");
        
        // Movie credits
        Assert.NotNull(movieCreditsResponse);
        Assert.True(movieCreditsResponse.Id > 0, "Movie credits Id must be a positive number");
        Assert.NotEmpty(movieCreditsResponse.Cast);
        TmdbMovieCastDataModel firstCast = movieCreditsResponse.Cast[0];
        Assert.True(firstCast.Gender >= 0, "Movie cast Gender must not be a negative number");
        Assert.True(firstCast.Id > 0, "Movie cast Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstCast.KnownForDepartment), "Movie cast KnownForDepartment must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCast.Name), "Movie cast Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCast.OriginalName), "Movie cast OriginalName must not be empty");
        Assert.True(firstCast.Popularity >= 0.0, "Movie cast Popularity must not be a negative decimal number");
        Assert.False(String.IsNullOrWhiteSpace(firstCast.Character), "Movie cast Character must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCast.CreditId), "Movie cast CreditId must not be empty");
        Assert.True(firstCast.Order >= 0, "Movie cast Order must not be a negative number");
        Assert.NotEmpty(movieCreditsResponse.Crew);
        TmdbMovieCrewDataModel firstCrew = movieCreditsResponse.Crew[0];
        Assert.True(firstCrew.Gender >= 0, "Movie crew Gender must not be a negative number");
        Assert.True(firstCrew.Id > 0, "Movie crew Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.KnownForDepartment), "Movie crew KnownForDepartment must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.Name), "Movie crew Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.OriginalName), "Movie crew OriginalName must not be empty");
        Assert.True(firstCrew.Popularity >= 0.0, "Movie crew Popularity must not be a negative decimal number");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.CreditId), "Movie crew CreditId must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.Department), "Movie crew Department must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.Job), "Movie crew Job must not be empty");
    }

